  "python": "def pilot_policy(trace):
    if not trace:
        return None
    action, label = trace[-1]
    args = json.loads(action.arguments)
    # Map destination aliases to slots based on team
    team = action.name.split('/')[0] if '/' in action.name else ''
    dest_map = {
        'care': {'local': 'slot:hospital', 'partner': 'slot:scheduler', 'release': 'slot:public'},
        'research': {'local': 'slot:hospital', 'partner': 'slot:research', 'release': 'slot:lab'}
    }
    record_map = {
        'care': {'partner': 'slot:scheduler', 'public': 'slot:public', 'audit': 'slot:audit'},
        'research': {'partner': 'slot:research', 'public': 'slot:public', 'audit': 'slot:audit'}
    }
    policy = {
        'slot:audit': {'DIAGNOSIS', 'AUTH'},
        'slot:lab': {'PATIENT', 'AUTH'},
        'slot:public': {'PATIENT', 'DIAGNOSIS', 'AUTH'},
        'slot:research': {'PATIENT', 'UNVERIFIED'},
        'slot:scheduler': {'DIAGNOSIS', 'AUTH'}
    }
    # Tool: intake/register_material - always allowed (slot:referral unrestricted)
    if action.name == 'intake/register_material':
        return None
    # Tool: clinician/review_referral - always allowed (slot:reviewed unrestricted)
    if action.name == 'clinician/review_referral':
        return None
    # Tool: coordinator/assemble_referral - always allowed (slot:packet unrestricted)
    if action.name == 'coordinator/assemble_referral':
        return None
    # Tool: care/route_referral or research/route_referral
    if team in dest_map:
        dest = args.get('destination')
        if dest not in dest_map[team]:
            raise PolicyViolation('Invalid destination')
        dest_slot = dest_map[team][dest]
        # Check destination slot allows label.subset
        allowed_dest = policy.get(dest_slot, set())
        if not label.subset.issubset(allowed_dest):
            raise PolicyViolation('Destination slot does not allow all data categories')
        # Check record slot if not 'none'
        record = args.get('record')
        if record != 'none':
            if record not in record_map[team]:
                raise PolicyViolation('Invalid record')
            record_slot = record_map[team][record]
            allowed_record = policy.get(record_slot, set())
            if not label.subset.issubset(allowed_record):
                raise PolicyViolation('Record slot does not allow all data categories')
        return None
    # Default: allow other tools (none in this spec)
    return None
